const upsertPriceListItem = `-- name: UpsertPriceListItem :exec
INSERT INTO pos_price_list_items (tenant_id, property_id, price_list_id, product_id, price, is_sold, station_id, updated_by)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (price_list_id, product_id) DO UPDATE SET price = EXCLUDED.price, is_sold = EXCLUDED.is_sold, station_id = EXCLUDED.station_id,
    updated_at = now(), updated_by = EXCLUDED.updated_by
`

type UpsertPriceListItemParams struct {
	TenantID    int64
	PropertyID  int64
	PriceListID int64
	ProductID   int64
	Price       decimal.Decimal
	IsSold      bool
	StationID   *int64
	ActorID     *int64
}

func (q *Queries) UpsertPriceListItem(ctx context.Context, arg UpsertPriceListItemParams) error {
	_, err := q.db.Exec(ctx, upsertPriceListItem,
		arg.TenantID,
		arg.PropertyID,
		arg.PriceListID,
		arg.ProductID,
		arg.Price,
		arg.IsSold,
		arg.StationID,
		arg.ActorID,
	)
	return err
}
